"use client"

import * as React from "react"
import * as PopoverPrimitive from "@radix-ui/react-popover"

import { cn } from "@/lib/utils"

function Popover(props: React.ComponentProps<typeof PopoverPrimitive.Root>) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger(props: React.ComponentProps<typeof PopoverPrimitive.Trigger>) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverAnchor(props: React.ComponentProps<typeof PopoverPrimitive.Anchor>) {
  return <PopoverPrimitive.Anchor data-slot="popover-anchor" {...props} />
}

function PopoverClose(props: React.ComponentProps<typeof PopoverPrimitive.Close>) {
  return <PopoverPrimitive.Close data-slot="popover-close" {...props} />
}

type Variant = "leader" | "brace" | "cut"

/* Each variant hangs the panel its own distance off: the leader's length, the brace's small gap
   (Radix adds the brace's own height), and nothing at all for the cut, which rides over its opener. */
const OFFSET: Record<Variant, number> = { leader: 27 /* --db-space-5 */, brace: 6, cut: 0 }

/**
 * A panel hung from what opened it. leader (the default): on a leader line, which joins the panel to
 * the trigger when it sits above or below and aligns to an edge (the default is the trigger's start
 * edge). brace: the panel's width gathered by a brace to one point at the trigger. cut: the panel's
 * edge cuts through the trigger's words and the panel rides over their lower half. Other menus and
 * pickers wear the same `db-pop` panel.
 */
function PopoverContent({
  className,
  variant = "leader",
  align = variant === "brace" ? "center" : "start",
  sideOffset = OFFSET[variant],
  collisionPadding = 20,
  arrowPadding = 24,
  style,
  children,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content> & { variant?: Variant }) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content
        data-slot="popover-content"
        data-variant={variant === "leader" ? undefined : variant}
        align={align}
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        arrowPadding={arrowPadding}
        style={{ "--db-pop-gap": `${sideOffset}px`, ...style } as React.CSSProperties}
        className={cn("db-pop", className)}
        {...props}
      >
        {children}
        {variant === "brace" && (
          // The brace's two ends curl at the panel's corners; its point is Radix's arrow, which Radix
          // keeps over the trigger's middle even when the panel shifts to stay on screen.
          <span className="db-pop-brace" aria-hidden="true">
            <span className="db-pop-brace-arms">
              <PopoverPrimitive.Arrow asChild>
                <span className="db-pop-brace-point" />
              </PopoverPrimitive.Arrow>
            </span>
          </span>
        )}
      </PopoverPrimitive.Content>
    </PopoverPrimitive.Portal>
  )
}

export { Popover, PopoverTrigger, PopoverContent, PopoverAnchor, PopoverClose }

@layer components {
  /* ── db-pop ── popover: a panel hung from what opened it, on a leader line.
     Keyed on the class and [data-state] alone, so the menus and pickers that
     wear db-pop (dropdown menu, combobox, date picker) hang the same way.
     Radix places it (side, align, sideOffset); --db-pop-gap is that offset. */
  .db-pop {
    --db-pop-gap: 8px; --db-pop-lead: 1.1em;
    position: relative; z-index: 50; padding: var(--db-space-4) var(--db-space-5); overflow: visible;
    max-width: min(26rem, calc(100vw - 2 * var(--db-margin)));
    background: var(--db-paper); color: var(--db-graphite); box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong);
    outline: 0;
    animation: db-pop-in var(--db-moderato) var(--db-exhale);
  }
  .db-pop[data-state="closed"] { animation: db-pop-out var(--db-allegro) var(--db-breath) forwards; }
  .db-pop[data-side="top"] { --db-pop-from: 4px; }
  @keyframes db-pop-in { from { opacity: 0; translate: 0 var(--db-pop-from, -4px); } }
  @keyframes db-pop-out { to { opacity: 0; } }

  /* The leader: a dot on the trigger's edge and a line dropping to the panel. */
  .db-pop:is([data-side="bottom"], [data-side="top"])::before,
  .db-pop:is([data-side="bottom"], [data-side="top"])::after { content: ""; position: absolute; pointer-events: none; }
  .db-pop:is([data-side="bottom"], [data-side="top"])::before { inset-inline-start: var(--db-pop-lead); width: var(--db-hairline); height: var(--db-pop-gap); background: var(--db-ink); }
  .db-pop:is([data-side="bottom"], [data-side="top"])::after { inset-inline-start: calc(var(--db-pop-lead) - 2px); width: 5px; height: 5px; border-radius: 50%; background: var(--db-ink); }
  .db-pop[data-align="end"] { --db-pop-lead: calc(100% - 1.1em); }
  .db-pop[data-align="center"] { --db-pop-lead: 50%; }
  .db-pop[data-side="bottom"]::before { bottom: 100%; transform-origin: 50% 0; }
  .db-pop[data-side="bottom"]::after { bottom: calc(100% + var(--db-pop-gap) - 2.5px); }
  .db-pop[data-side="top"]::before { top: 100%; transform-origin: 50% 100%; }
  .db-pop[data-side="top"]::after { top: calc(100% + var(--db-pop-gap) - 2.5px); }
  .db-pop[data-state="open"]::after { animation: db-land var(--db-moderato) var(--db-spiccato) backwards; }
  .db-pop[data-state="open"]::before { animation: db-draw-y var(--db-moderato) var(--db-breath) 60ms backwards; }

  /* Forced colours drop the panel's hairline (a box-shadow) and paint the leader's background away. */
  @media (forced-colors: active) {
    /* The hairline is a box-shadow, which forced colours drop. A border, not an outline: Radix's menus
       set an inline outline: none on their panel, which no stylesheet can outrank. */
    .db-pop { border: var(--db-hairline) solid CanvasText; }
    .db-pop::before, .db-pop::after { forced-color-adjust: none; background: CanvasText; }
    .db-pop[data-variant="brace"] { border: 0; } /* boxless: its brace is the edge */
  }

  /* ── brace ── the panel's width gathered to one point at the trigger, like the brace that joins a
     score's staves or an underbrace that sums a span. The ends curl at the panel's corners (this
     element's own ::before and ::after); the arms and the point are Radix's arrow, which Radix keeps
     over the trigger's middle when the panel shifts (it measures from .db-pop-brace-arms, which is centred
     on the panel, so no correction is needed). The arms run long and .db-pop-brace-arms clips
     them where the curls begin. Drawn as for a panel above; Radix turns the point over for one below. */
  .db-pop[data-variant="brace"] {
    --db-pop-brace-r: var(--db-space-2); --db-pop-brace-g: var(--db-space-2); --db-pop-brace-in: var(--db-space-5);
    padding: var(--db-space-3) var(--db-pop-brace-in) var(--db-space-4); box-shadow: none; /* the brace is the panel's edge */
  }
  .db-pop:is([data-variant="brace"], [data-variant="cut"])::before,
  .db-pop:is([data-variant="brace"], [data-variant="cut"])::after { content: none; }
  .db-pop-brace, .db-pop-brace-arms { position: absolute; inset-block: 0; pointer-events: none; }
  .db-pop-brace { inset-inline: var(--db-pop-brace-in); } /* spans the words, not the paper round them */
  .db-pop-brace-arms { left: var(--db-pop-brace-r); right: var(--db-pop-brace-r); overflow-x: clip; overflow-y: visible; clip-path: inset(-3em 0); }
  .db-pop-brace-point { position: relative; width: 0; height: calc(var(--db-pop-brace-g) + 2 * var(--db-pop-brace-r)); }
  .db-pop-brace::before, .db-pop-brace::after,
  .db-pop-brace-point::before, .db-pop-brace-point::after { content: ""; position: absolute; border: 0 solid var(--db-ink); }
  .db-pop-brace-point::before, .db-pop-brace-point::after {
    top: calc(var(--db-pop-brace-g) + var(--db-pop-brace-r) - var(--db-hairline)); width: 100vw; height: calc(var(--db-pop-brace-r) + var(--db-hairline));
    border-top-width: var(--db-hairline);
  }
  .db-pop-brace-point::before { right: 0; border-right-width: var(--db-hairline); border-top-right-radius: var(--db-pop-brace-r); }
  .db-pop-brace-point::after { left: 0; border-left-width: var(--db-hairline); border-top-left-radius: var(--db-pop-brace-r); }
  .db-pop-brace::before, .db-pop-brace::after { width: var(--db-pop-brace-r); height: var(--db-pop-brace-r); }
  .db-pop-brace::before { left: 0; border-left-width: var(--db-hairline); }
  .db-pop-brace::after { right: 0; border-right-width: var(--db-hairline); }
  .db-pop[data-side="bottom"] .db-pop-brace::before, .db-pop[data-side="bottom"] .db-pop-brace::after { top: calc(-1 * (var(--db-pop-brace-g) + var(--db-pop-brace-r))); border-top-width: var(--db-hairline); }
  .db-pop[data-side="top"] .db-pop-brace::before, .db-pop[data-side="top"] .db-pop-brace::after { top: calc(100% + var(--db-pop-brace-g)); border-bottom-width: var(--db-hairline); }
  .db-pop[data-side="bottom"] .db-pop-brace::before { border-top-left-radius: var(--db-pop-brace-r); }
  .db-pop[data-side="bottom"] .db-pop-brace::after { border-top-right-radius: var(--db-pop-brace-r); }
  .db-pop[data-side="top"] .db-pop-brace::before { border-bottom-left-radius: var(--db-pop-brace-r); }
  .db-pop[data-side="top"] .db-pop-brace::after { border-bottom-right-radius: var(--db-pop-brace-r); }
  .db-pop[data-variant="brace"]:is([data-side="left"], [data-side="right"]) .db-pop-brace { display: none; } /* a brace gathers a width; beside the trigger there's none to gather */
  /* Gather: the arms open out from the middle to the panel's ends, then the ends curl in. */
  .db-pop[data-state="open"] .db-pop-brace-arms { animation: db-pop-brace-open var(--db-moderato) var(--db-exhale) backwards; }
  .db-pop[data-state="open"] .db-pop-brace::before, .db-pop[data-state="open"] .db-pop-brace::after { animation: db-pop-out var(--db-allegro) var(--db-breath) reverse var(--db-moderato) backwards; }
  @keyframes db-pop-brace-open { from { clip-path: inset(-3em 50%); } }

  /* ── cut ── the panel's edge cuts through the trigger's words at half their height and rides over
     the lower half, the way SPECTRA's title is cut by a line. There is no leader: the join is the cut.
     Radix gives the trigger's height; the edge the words are cut by is set in ink. */
  .db-pop[data-variant="cut"] { --db-pop-from: 0px; --db-pop-cut: calc(var(--radix-popover-trigger-height, 0px) / 2); }
  .db-pop[data-variant="cut"][data-side="bottom"] { translate: 0 calc(-1 * var(--db-pop-cut)); box-shadow: inset 0 var(--db-hairline) var(--db-ink), inset 0 0 0 var(--db-hairline) var(--db-rule-strong); }
  .db-pop[data-variant="cut"][data-side="top"] { translate: 0 var(--db-pop-cut); box-shadow: inset 0 calc(-1 * var(--db-hairline)) var(--db-ink), inset 0 0 0 var(--db-hairline) var(--db-rule-strong); }
  .db-pop[data-variant="cut"][data-state="open"] { animation-duration: var(--db-andante); }
}
